package io.github.diodeme.ji.session.tree;

import io.github.diodeme.ji.ai.ModelRef;
import java.util.Map;
import java.util.Optional;

/** Optional Session adapter projection for the configuration captured by an active Run. */
public interface SessionRunConfigurationSource {
    Optional<RunConfiguration> activeRunConfiguration(String sessionId);

    record RunConfiguration(long revision, ModelRef model, Map<String, Object> modelOptions) {
        public RunConfiguration {
            if (revision < 0 || model == null) {
                throw new IllegalArgumentException("invalid Run configuration");
            }
            modelOptions = Map.copyOf(modelOptions);
        }
    }
}
